-- Daily challenges for 2026-11-25: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-25. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.
-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('spending-time-near-water', 'Spending Time Near Water', 'For anyone who feels calmer by a river, a lake or even a running tap. Each day is one small way to notice, visit and enjoy the water around you, at home, in your neighborhood and through every season, safely and without spending much.', 'Grounding', 365, array['Grounding', 'Mindfulness', 'Stress']::text[], 1, '2026-11-25T17:00:00+00:00'::timestamptz),
  ('giving-your-senses-a-rest', 'Giving Your Senses a Rest', 'For anyone worn out by noise, bright light, screens and busy places. Each day is one small way to turn the world down a little, give your eyes, ears and attention a break, and plan calmer moments at home, at work and with people.', 'Rest', 365, array['Stress', 'Self-Care', 'Burnout']::text[], 1, '2026-11-25T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('spending-time-near-water', 'giving-your-senses-a-rest');

